const FIRST_INSURANCE_NUMERATOR = 11;
const FIRST_INSURANCE_DENOMINATOR = 10;

const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * FIRST_INSURANCE_NUMERATOR) / FIRST_INSURANCE_DENOMINATOR;

/** All rounding is in the MHPCO's favor — always up. */
const roundInMHPCOsFavor = Math.ceil;

interface InsuredItem {
  type: string;
}

const sumBasePremiums = (items: InsuredItem[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quotePremium = (step: Step): QuoteResult => {
  const base = sumBasePremiums((step.items ?? []) as InsuredItem[]);

  return {
    premium: roundInMHPCOsFavor(applyFirstInsuranceSurcharge(base)) +
      PROCESSING_FEE,
  };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quotePremium),
});
